#include <stdio.h>
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    long long a[100005];
    for (int i = 0; i < n; i++) scanf("%lld", &a[i]);
    for (int i = 0; i < n - 1; i++) {
        if (a[i] != 0 && a[i] == a[i + 1]) {
            a[i] *= 2; a[i + 1] = 0; i++;
        }
    }
    long long res[100005]; int idx = 0;
    for (int i = 0; i < n; i++) if (a[i] != 0) res[idx++] = a[i];
    while (idx < n) res[idx++] = 0;
    for (int i = 0; i < n; i++) {
        if (i > 0) putchar(' ');
        printf("%lld", res[i]);
    }
    printf("\n");
    return 0;
}

