            a[i] *= 2; a[i + 1] = 0; i++;
        }
    }
    vector<long long> res;
    for (int i = 0; i < n; i++) if (a[i] != 0) res.push_back(a[i]);
    while (res.size() < (size_t)n) res.push_back(0);
    for (int i = 0; i < n; i++) {
        if (i > 0) cout << " ";
        cout << res[i];
    }
    cout << "\n";
    return 0;
}

code.Java:
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            long[] a = new long[n];
            for (int i = 0; i < n; i++) a[i] = sc.nextLong();
            for (int i = 0; i < n - 1; i++) {
                if (a[i] != 0 && a[i] == a[i + 1]) {
                    a[i] *= 2; a[i + 1] = 0; i++;
                }
            }
            StringBuilder sb = new StringBuilder();
            int count = 0;
            for (int i = 0; i < n; i++) {
                if (a[i] != 0) {
                    if (sb.length() > 0) sb.append(" ");
                    sb.append(a[i]); count++;
                }
            }
            while (count < n) {
                if (sb.length() > 0) sb.append(" ");
                sb.append(0); count++;
            }
            System.out.println(sb.toString());
        }
    }
}

