const fs = require("fs");
function main() {
    const toks = fs.readFileSync(0, "utf-8").trim().split(/\s+/);
    if (!toks || toks.length === 0 || toks[0] === "") return;
    const n = parseInt(toks[0], 10);
    const arr = toks.slice(1, n + 1).map(x => BigInt(x));
    let i = 0;
    while (i < n - 1) {
        if (arr[i] !== 0n && arr[i] === arr[i + 1]) {
            arr[i] *= 2n; arr[i + 1] = 0n; i += 2;
        } else i++;
    }
    const nonZeros = arr.filter(x => x !== 0n);
    while (nonZeros.length < n) nonZeros.push(0n);
    console.log(nonZeros.map(x => x.toString()).join(" "));
}
main();

